SELECT gen_random_uuid()::text, 'formula', '$\frac{1}{\rho}$', 'Curvature of a Bent Beam', '$\frac{1}{\rho} = \frac{M}{EI},\qquad \sigma = \frac{Ey}{\rho}$', '$\text{1/m}$', 'How sharply a beam bends under a moment.', '[{"symbol":"$\\rho$","meaning":"radius of curvature","unit":"$\\text{m}$"},{"symbol":"$E$","meaning":"modulus of elasticity","unit":"$\\text{Pa}$"},{"symbol":"$I$","meaning":"moment of inertia of the section","unit":"$\\text{m}^4$"}]'::jsonb, 'Bending a wire round a drum of radius $\rho$: $\sigma = \frac{Ed}{2\rho}$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'flexural stress' AND s."active"), NULL, false, 'PENDING', now(), now()
