SELECT gen_random_uuid()::text, 'formula', '$\tau = \frac{VQ}{Ib}$', 'Shear Stress in Beams', '$\tau = \frac{VQ}{Ib}$', '$\text{Pa}$', 'The horizontal (and vertical) shear stress at a level in a beam.', '[{"symbol":"$V$","meaning":"shear force","unit":"$\\text{N}$"},{"symbol":"$Q$","meaning":"first moment about the neutral axis of the area beyond the level","unit":"$\\text{m}^3$"},{"symbol":"$I$","meaning":"moment of inertia of the section","unit":"$\\text{m}^4$"},{"symbol":"$b$","meaning":"width at that level","unit":"$\\text{m}$"}]'::jsonb, 'It is zero at the top and bottom and usually greatest at the neutral axis.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'shear stress in beams' AND s."active"), NULL, false, 'PENDING', now(), now()
