SELECT gen_random_uuid()::text, 'formula', '$EIy'''' = M$', 'Elastic Curve Equation', '$EI\frac{d^2y}{dx^2} = M(x)$', '$\text{N}\cdot\text{m}$', 'Integrate the moment twice to find the beam''s deflected shape.', '[{"symbol":"$E$","meaning":"modulus of elasticity","unit":"$\\text{Pa}$"},{"symbol":"$I$","meaning":"moment of inertia of the section","unit":"$\\text{m}^4$"},{"symbol":"$y$","meaning":"deflection","unit":"$\\text{m}$"},{"symbol":"$M$","meaning":"bending moment","unit":"$\\text{N}\\cdot\\text{m}$"}]'::jsonb, 'Constants come from the supports: y = 0 at a support, y'' = 0 at a fixed end.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'beam deflection' AND s."active"), NULL, false, 'PENDING', now(), now()
