SELECT gen_random_uuid()::text, 'formula', '$\delta_{\max}$', 'Deflections of Standard Beams', '$\text{cantilever: } \frac{PL^3}{3EI},\ \frac{wL^4}{8EI};\qquad \text{simple: } \frac{PL^3}{48EI},\ \frac{5wL^4}{384EI}$', '$\text{m}$', 'Greatest deflection for end/centre point loads and uniform loads.', '[{"symbol":"$P$","meaning":"load","unit":"$\\text{N}$"},{"symbol":"$w$","meaning":"uniform load","unit":"$\\text{N/m}$"},{"symbol":"$L$","meaning":"length or span","unit":"$\\text{m}$"},{"symbol":"$E$","meaning":"modulus of elasticity","unit":"$\\text{Pa}$"},{"symbol":"$I$","meaning":"moment of inertia of the section","unit":"$\\text{m}^4$"}]'::jsonb, 'Combine loads by adding deflections (superposition).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'beam deflection' AND s."active"), NULL, false, 'PENDING', now(), now()
