SELECT gen_random_uuid()::text, 'formula', '$\theta_{\max}$', 'Slopes of Standard Beams', '$\text{cantilever: } \frac{PL^2}{2EI},\ \frac{wL^3}{6EI};\qquad \text{simple (at supports): } \frac{PL^2}{16EI},\ \frac{wL^3}{24EI}$', '$\text{rad}$', 'Greatest slope for the same standard cases.', '[{"symbol":"$P$","meaning":"load","unit":"$\\text{N}$"},{"symbol":"$w$","meaning":"uniform load","unit":"$\\text{N/m}$"},{"symbol":"$L$","meaning":"length or span","unit":"$\\text{m}$"},{"symbol":"$E$","meaning":"modulus of elasticity","unit":"$\\text{Pa}$"},{"symbol":"$I$","meaning":"moment of inertia of the section","unit":"$\\text{m}^4$"}]'::jsonb, 'The answer is in radians.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'beam deflection' AND s."active"), NULL, false, 'PENDING', now(), now()
