SELECT gen_random_uuid()::text, 'formula', '$\theta_{B/A}$', 'Moment-Area Theorems', '$\theta_{B/A} = \int_A^B\frac{M}{EI}dx;\qquad t_{B/A} = \int_A^B\frac{M}{EI}x_B\,dx$', '$\text{m}$', 'Slope change is the area of the M/EI diagram; deviation is that area''s moment about the point.', '[{"symbol":"$\\theta_{B/A}$","meaning":"change of slope from A to B","unit":"$\\text{rad}$"},{"symbol":"$t_{B/A}$","meaning":"deviation of B from the tangent at A","unit":"$\\text{m}$"},{"symbol":"$x_B$","meaning":"distance measured from B","unit":"$\\text{m}$"}]'::jsonb, 'For a cantilever, take A at the fixed end: the tangent there is horizontal.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'beam deflection' AND s."active"), NULL, false, 'PENDING', now(), now()
