SELECT gen_random_uuid()::text, 'formula', '$\sigma$', 'Eccentric Axial Load', '$\sigma = \frac{P}{A} \pm \frac{Pec}{I};\qquad \text{rectangle: no tension if } e \le \frac{b}{6}$', '$\text{Pa}$', 'A load off the centroid adds bending to direct stress.', '[{"symbol":"$P$","meaning":"load","unit":"$\\text{N}$"},{"symbol":"$A$","meaning":"area","unit":"$\\text{m}^2$"},{"symbol":"$e$","meaning":"eccentricity of the load","unit":"$\\text{m}$"},{"symbol":"$I$","meaning":"moment of inertia of the section","unit":"$\\text{m}^4$"},{"symbol":"$c$","meaning":"distance to the extreme fibre","unit":"$\\text{m}$"}]'::jsonb, 'The middle-third rule: keep the load within the kern to avoid tension.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'combined stresses and mohr''s circle' AND s."active"), NULL, false, 'PENDING', now(), now()
