SELECT gen_random_uuid()::text, 'formula', '$\sigma_{x''}$', 'Plane Stress Transformation', '$\sigma_{x''} = \frac{\sigma_x + \sigma_y}{2} + \frac{\sigma_x - \sigma_y}{2}\cos2\theta + \tau_{xy}\sin2\theta,\quad \tau_{x''y''} = -\frac{\sigma_x - \sigma_y}{2}\sin2\theta + \tau_{xy}\cos2\theta$', '$\text{Pa}$', 'Stresses on an element rotated by θ.', '[{"symbol":"$\\sigma_x, \\sigma_y$","meaning":"normal stresses (tension positive)","unit":"$\\text{Pa}$"},{"symbol":"$\\tau_{xy}$","meaning":"shear stress","unit":"$\\text{Pa}$"},{"symbol":"$\\theta$","meaning":"rotation of the element, counter-clockwise","unit":null}]'::jsonb, 'The sum σx + σy is the same for every rotation.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'combined stresses and mohr''s circle' AND s."active"), NULL, false, 'PENDING', now(), now()
