SELECT gen_random_uuid()::text, 'formula', '$\sigma_{1,2}$', 'Principal Stresses', '$\sigma_{1,2} = \frac{\sigma_x + \sigma_y}{2} \pm \sqrt{\left(\frac{\sigma_x - \sigma_y}{2}\right)^2 + \tau_{xy}^2},\qquad \tan2\theta_p = \frac{2\tau_{xy}}{\sigma_x - \sigma_y}$', '$\text{Pa}$', 'The largest and smallest normal stresses, on planes with no shear.', '[{"symbol":"$\\sigma_x, \\sigma_y$","meaning":"normal stresses (tension positive)","unit":"$\\text{Pa}$"},{"symbol":"$\\tau_{xy}$","meaning":"shear stress","unit":"$\\text{Pa}$"}]'::jsonb, 'Principal planes are 45° from the planes of maximum shear.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'combined stresses and mohr''s circle' AND s."active"), NULL, false, 'PENDING', now(), now()
