SELECT gen_random_uuid()::text, 'formula', '$R$', 'Mohr''s Circle', '$C = \frac{\sigma_x + \sigma_y}{2},\qquad R = \sqrt{\left(\frac{\sigma_x - \sigma_y}{2}\right)^2 + \tau_{xy}^2} = \tau_{\max}$', '$\text{Pa}$', 'A circle that shows every state of stress at a point: centre C, radius R = the greatest in-plane shear.', '[{"symbol":"$\\sigma_x, \\sigma_y$","meaning":"normal stresses (tension positive)","unit":"$\\text{Pa}$"},{"symbol":"$\\tau_{xy}$","meaning":"shear stress","unit":"$\\text{Pa}$"}]'::jsonb, 'A rotation of θ on the element is 2θ on the circle.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'combined stresses and mohr''s circle' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
