SELECT gen_random_uuid()::text, 'formula', '$\tau_{\max}$', 'Combined Bending and Torsion of a Shaft', '$\tau_{\max} = \frac{16}{\pi d^3}\sqrt{M^2 + T^2},\qquad \sigma_{\max} = \frac{16}{\pi d^3}\left(M + \sqrt{M^2 + T^2}\right)$', '$\text{Pa}$', 'Peak shear and normal stress in a solid shaft that both bends and twists.', '[{"symbol":"$M$","meaning":"bending moment","unit":"$\\text{N}\\cdot\\text{m}$"},{"symbol":"$T$","meaning":"torque","unit":"$\\text{N}\\cdot\\text{m}$"},{"symbol":"$d$","meaning":"shaft diameter","unit":"$\\text{m}$"}]'::jsonb, '$\sqrt{M^2 + T^2}$ is the equivalent torque; $\frac12(M + \sqrt{M^2 + T^2})$ the equivalent moment.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'combined stresses and mohr''s circle' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS'
