SELECT gen_random_uuid()::text, 'formula', '$P_{cr}$', 'Euler Buckling Load', '$P_{cr} = \frac{\pi^2EI}{(KL)^2};\quad K = 1 \text{ (pinned)},\ 2 \text{ (fixed-free)},\ 0.7 \text{ (fixed-pinned)},\ 0.5 \text{ (fixed-fixed)}$', '$\text{N}$', 'The axial load at which a slender column buckles.', '[{"symbol":"$E$","meaning":"modulus of elasticity","unit":"$\\text{Pa}$"},{"symbol":"$I$","meaning":"the SMALLEST moment of inertia","unit":"$\\text{m}^4$"},{"symbol":"$L$","meaning":"length or span","unit":"$\\text{m}$"},{"symbol":"$K$","meaning":"effective-length factor","unit":null}]'::jsonb, 'A flagpole (fixed-free) buckles at a quarter of the pinned-pinned load.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'columns' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$\sigma_{cr}$', 'Slenderness Ratio and Critical Stress', '$\sigma_{cr} = \frac{\pi^2E}{(KL/r)^2},\qquad r = \sqrt{\frac IA}$', '$\text{Pa}$', 'Euler''s buckling stress; valid only while it stays below the proportional limit.', '[{"symbol":"$E$","meaning":"modulus of elasticity","unit":"$\\text{Pa}$"},{"symbol":"$KL/r$","meaning":"slenderness ratio","unit":null},{"symbol":"$r$","meaning":"least radius of gyration","unit":"$\\text{m}$"}]'::jsonb, 'For steel (σ_pl ≈ 200 MPa) Euler applies above about $\frac{KL}{r} \approx 100$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'columns' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$\sigma_{cr}$', 'J. B. Johnson Formula', '$\sigma_{cr} = \sigma_y - \frac{\sigma_y^2}{4\pi^2E}\left(\frac{KL}{r}\right)^2$', '$\text{Pa}$', 'Critical stress for intermediate columns, too short for Euler.', '[{"symbol":"$\\sigma_y$","meaning":"yield strength","unit":"$\\text{Pa}$"},{"symbol":"$E$","meaning":"modulus of elasticity","unit":"$\\text{Pa}$"},{"symbol":"$KL/r$","meaning":"slenderness ratio","unit":null}]'::jsonb, 'It meets Euler''s curve tangentially at $\frac{KL}{r} = \sqrt{\frac{2\pi^2E}{\sigma_y}}$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'columns' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
