SELECT gen_random_uuid()::text, 'formula', '$\sigma$', 'Thin Sphere Stress', '$\sigma = \frac{pD}{4t}$', '$\text{Pa}$', 'Stress in a thin spherical shell, the same in every direction.', '[{"symbol":"$p$","meaning":"internal pressure","unit":"$\\text{Pa}$"},{"symbol":"$D$","meaning":"inside diameter","unit":"$\\text{m}$"},{"symbol":"$t$","meaning":"wall thickness","unit":"$\\text{m}$"}]'::jsonb, 'A sphere needs half the wall of a cylinder of the same diameter.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'thin-walled pressure vessels' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
