SELECT gen_random_uuid()::text, 'formula', '$\sigma_t$', 'Thick-Walled Cylinder (Lamé)', '$\sigma_{t,\text{inner}} = p\,\frac{r_o^2 + r_i^2}{r_o^2 - r_i^2}$', '$\text{Pa}$', 'The greatest hoop stress in a thick cylinder, at the bore.', '[{"symbol":"$p$","meaning":"internal pressure","unit":"$\\text{Pa}$"},{"symbol":"$r_i, r_o$","meaning":"inner and outer radii","unit":"$\\text{m}$"}]'::jsonb, 'For a thin wall it reduces to pD/(2t).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'thin-walled pressure vessels' AND s."active"), NULL, false, 'PENDING', now(), now()
