SELECT gen_random_uuid()::text, 'formula', '$P_s$', 'Rivet Shear Capacity', '$P_s = n\,m\,\frac{\pi d^2}{4}\tau_{\text{allow}}$', '$\text{N}$', 'The load a riveted joint can carry before its rivets shear.', '[{"symbol":"$n$","meaning":"rivets","unit":null},{"symbol":"$m$","meaning":"shear planes per rivet (1 lap, 2 butt with two cover plates)","unit":null},{"symbol":"$d$","meaning":"rivet diameter","unit":"$\\text{m}$"},{"symbol":"$\\tau_{\\text{allow}}$","meaning":"allowable shear","unit":"$\\text{Pa}$"}]'::jsonb, 'Use the hole (driven) diameter if the problem says so.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'riveted and welded joints' AND s."active"), NULL, false, 'PENDING', now(), now()
