SELECT gen_random_uuid()::text, 'formula', '$P_t$', 'Plate Bearing and Tearing Capacity', '$P_b = n\,d\,t\,\sigma_b;\qquad P_t = (b - n''d)\,t\,\sigma_t$', '$\text{N}$', 'The joint''s capacity in bearing on the holes and in tension across the net section.', '[{"symbol":"$t$","meaning":"plate thickness","unit":"$\\text{m}$"},{"symbol":"$b$","meaning":"plate width","unit":"$\\text{m}$"},{"symbol":"$n''$","meaning":"holes across the critical section","unit":null},{"symbol":"$\\sigma_b, \\sigma_t$","meaning":"allowable bearing and tensile stress","unit":"$\\text{Pa}$"}]'::jsonb, 'The joint''s strength is the smallest of shear, bearing and tearing.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'riveted and welded joints' AND s."active"), NULL, false, 'PENDING', now(), now()
