SELECT gen_random_uuid()::text, 'formula', '$\eta$', 'Joint Efficiency', '$\eta = \frac{\min(P_s, P_b, P_t)}{b\,t\,\sigma_t}$', NULL, 'How strong a joint is compared with the plate without holes.', '[{"symbol":"$b\\,t\\,\\sigma_t$","meaning":"strength of the solid plate","unit":"$\\text{N}$"}]'::jsonb, 'Pressure vessels use it: t = pD/(2σ_t η).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'riveted and welded joints' AND s."active"), NULL, true, 'PENDING', now(), now()
