SELECT gen_random_uuid()::text, 'formula', '$P$', 'Fillet Weld Strength', '$P = 0.707\,a\,L\,\tau_{\text{allow}}$', '$\text{N}$', 'Load capacity of a fillet weld, which fails in shear through its throat (0.707 × leg).', '[{"symbol":"$a$","meaning":"leg size of the weld","unit":"$\\text{m}$"},{"symbol":"$L$","meaning":"total weld length","unit":"$\\text{m}$"},{"symbol":"$\\tau_{\\text{allow}}$","meaning":"allowable shear on the throat","unit":"$\\text{Pa}$"}]'::jsonb, 'For an eccentric member, split the weld length so each line''s moment balances.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Deformable Bodies' AND t."subject" = 'ESAS' AND s."normKey" = 'riveted and welded joints' AND s."active"), NULL, false, 'PENDING', now(), now()
